import{_ as d,o as r,c as o,a2 as a}from"./chunks/framework.BbQrW5_t.js";const q=JSON.parse('{"title":"苏轼是如何度过生命中的至暗时刻","description":"","frontmatter":{"title":"苏轼是如何度过生命中的至暗时刻","date":"2026-07-14T00:00:00.000Z","tags":["视频笔记","苏轼","乌台诗案","黄州"],"source":"https://weixin.qq.com/sph/AMdllun3UJ"},"headers":[],"relativePath":"study/dian-di/20260714-苏轼至暗时刻.md","filePath":"study/dian-di/20260714-苏轼至暗时刻.md","lastUpdated":1785135535000}'),e={name:"study/dian-di/20260714-苏轼至暗时刻.md"};function n(s,t,h,l,i,u){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="苏轼是如何度过生命中的至暗时刻" tabindex="-1">苏轼是如何度过生命中的至暗时刻 <a class="header-anchor" href="#苏轼是如何度过生命中的至暗时刻" aria-label="Permalink to &quot;苏轼是如何度过生命中的至暗时刻&quot;">​</a></h1><h2 id="📹-视频信息" tabindex="-1">📹 视频信息 <a class="header-anchor" href="#📹-视频信息" aria-label="Permalink to &quot;📹 视频信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>标题</strong></td><td>苏轼是如何度过生命中的至暗时刻</td></tr><tr><td><strong>作者</strong></td><td>李金芳微纪录</td></tr><tr><td><strong>发布日期</strong></td><td>2026年7月14日</td></tr><tr><td><strong>标签</strong></td><td>#黄州 #乌台诗案 #寻找东坡足迹</td></tr><tr><td><strong>来源</strong></td><td><a href="https://weixin.qq.com/sph/AMdllun3UJ" target="_blank" rel="noreferrer">微信视频号</a></td></tr></tbody></table><p><strong>互动数据：</strong></p><table tabindex="0"><thead><tr><th>👍 点赞</th><th>🔗 转发</th><th>❤️ 喜欢</th><th>💬 评论</th></tr></thead><tbody><tr><td>333</td><td>399</td><td>328</td><td>76</td></tr></tbody></table><hr><h2 id="🔑-关键知识点" tabindex="-1">🔑 关键知识点 <a class="header-anchor" href="#🔑-关键知识点" aria-label="Permalink to &quot;🔑 关键知识点&quot;">​</a></h2><h3 id="一、至暗时刻-乌台诗案-1079年" tabindex="-1">一、至暗时刻：乌台诗案（1079年） <a class="header-anchor" href="#一、至暗时刻-乌台诗案-1079年" aria-label="Permalink to &quot;一、至暗时刻：乌台诗案（1079年）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>起因</strong></td><td>苏轼调任湖州知州后上《湖州谢上表》，被政敌摘取表中语句弹劾&quot;愚弄朝廷、妄尊自大&quot;</td></tr><tr><td><strong>指控</strong></td><td>从其诗作中摘取断句，罗织&quot;谤讪朝政&quot;之罪</td></tr><tr><td><strong>经过</strong></td><td>苏轼被逮捕押解入京，关入御史台（乌台）狱中约百余日</td></tr><tr><td><strong>结果</strong></td><td>在多方营救下免于死罪，贬为黄州团练副使（无实权、不得签书公事）</td></tr></tbody></table><h3 id="二、黄州岁月-1080—1084年-从绝境到重生" tabindex="-1">二、黄州岁月（1080—1084年）：从绝境到重生 <a class="header-anchor" href="#二、黄州岁月-1080—1084年-从绝境到重生" aria-label="Permalink to &quot;二、黄州岁月（1080—1084年）：从绝境到重生&quot;">​</a></h3><p>苏轼在黄州完成了人生最重要的蜕变：</p><p><strong>1. 生活困境 → 躬耕自立</strong></p><ul><li>俸禄微薄，全家生活困顿</li><li>友人马正卿请得废弃营地数十亩，苏轼亲自开荒种田</li><li>因地在东坡，自号**&quot;东坡居士&quot;**</li></ul><p><strong>2. 精神疗愈方式</strong></p><table tabindex="0"><thead><tr><th>方式</th><th>具体表现</th></tr></thead><tbody><tr><td><strong>耕种劳动</strong></td><td>亲自动手开荒种地，体力的劳作带来内心的安定</td></tr><tr><td><strong>佛道修心</strong></td><td>研读佛经、道书，与僧道交往，参悟生死</td></tr><tr><td><strong>山水寄情</strong></td><td>游历赤壁等黄州山水，在自然中寻找精神出口</td></tr><tr><td><strong>文学创作</strong></td><td>将痛苦转化为传世之作，以写作为自我救赎</td></tr><tr><td><strong>交友论道</strong></td><td>与米芾等友人交往，在精神交流中获得支撑</td></tr></tbody></table><p><strong>3. 传世名作（黄州时期）</strong></p><table tabindex="0"><thead><tr><th>作品</th><th>时间</th><th>名句</th></tr></thead><tbody><tr><td>《念奴娇·赤壁怀古》</td><td>1082年</td><td>&quot;大江东去，浪淘尽，千古风流人物&quot;</td></tr><tr><td>《前赤壁赋》</td><td>1082年秋</td><td>&quot;寄蜉蝣于天地，渺沧海之一粟&quot;</td></tr><tr><td>《后赤壁赋》</td><td>1082年冬</td><td>&quot;山高月小，水落石出&quot;</td></tr><tr><td>《定风波》</td><td>1082年春</td><td>&quot;竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生&quot;</td></tr><tr><td>《临江仙》</td><td>—</td><td>&quot;小舟从此逝，江海寄余生&quot;</td></tr></tbody></table><h3 id="三、核心启示" tabindex="-1">三、核心启示 <a class="header-anchor" href="#三、核心启示" aria-label="Permalink to &quot;三、核心启示&quot;">​</a></h3><blockquote><p>苏轼度过至暗时刻的关键不是&quot;忍&quot;，而是**&quot;转化&quot;**：</p></blockquote><ol><li><strong>接受现实</strong> — 不沉溺于冤屈感，接受贬谪处境</li><li><strong>向下扎根</strong> — 劳动、种地，在具体生活中重建秩序感</li><li><strong>向上生长</strong> — 读书、写作、参禅，在精神世界中超越苦难</li><li><strong>向外连接</strong> — 交友、游历、寄情山水，不自我封闭</li><li><strong>向内观照</strong> — 在赤壁的千古江山面前，将个人荣辱放在更宏大的时间尺度中审视</li></ol><hr><h2 id="💡-个人思考" tabindex="-1">💡 个人思考 <a class="header-anchor" href="#💡-个人思考" aria-label="Permalink to &quot;💡 个人思考&quot;">​</a></h2><p>苏轼的黄州岁月提供了一个应对人生困境的完整范式：<strong>不是逃避痛苦，而是将痛苦转化为创造的燃料</strong>。他在最绝望的处境中，反而创作出千古传诵的名篇，这种&quot;苦难转化力&quot;值得学习。</p><p>对现代人而言，当面临职业挫折、人生低谷时，可以借鉴苏轼的&quot;五向&quot;疗愈法：向下扎根（具体行动）、向上生长（精神追求）、向外连接（社交支持）、向内观照（自我反思），最终实现苦难的超越与转化。</p>',24)])])}const b=d(e,[["render",n]]);export{q as __pageData,b as default};
